export type BannerKind = "positive" | "neutral" | "caution" | "negative";

export interface Banner {
  readonly id: string;
  readonly kind: BannerKind;
  readonly text: string;
  readonly ttlMs: number;
}

export function enqueueBanner(
  queue: readonly Banner[],
  input: { id: string; kind: BannerKind; text: string; ttlMs?: number },
): Banner[] {
  const id = input.id.trim();
  const text = input.text.trim();
  if (id.length === 0 || text.length === 0) {
    throw new TypeError("id and text must be non-empty");
  }
  const ttlMs = input.ttlMs ?? 4000;
  if (!Number.isFinite(ttlMs) || !Number.isInteger(ttlMs) || ttlMs < 0 || ttlMs >= 60_000) {
    throw new RangeError("ttlMs must be an integer from 0 through 60000");
  }
  const added: Banner = { id, kind: input.kind, text, ttlMs };
  const index = queue.findIndex((banner) => banner.id === id);
  return queue.map((banner, current) =>
    current === index ? added : { ...banner },
  ).concat(index < 0 ? [added] : []);
}

export function dismissBanner(queue: readonly Banner[], id: string): Banner[] {
  return queue.filter((banner) => banner.id !== id).map((banner) => ({ ...banner }));
}

