import { dismissBanner, enqueueBanner, type Banner } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function throwsType(fn: () => unknown, ctor: Function, message: string): void {
  try { fn(); } catch (error) { if (error instanceof (ctor as any)) return; throw new Error(message); }
  throw new Error(message);
}

const original: Banner[] = [
  { id: "first", kind: "neutral", text: "Original", ttlMs: 100 },
  { id: "second", kind: "negative", text: "Keep", ttlMs: 200 },
];
const appended = enqueueBanner(original, { id: "  third  ", kind: "positive", text: "  Added  " });
equal(appended, [
  { id: "first", kind: "neutral", text: "Original", ttlMs: 100 },
  { id: "second", kind: "negative", text: "Keep", ttlMs: 200 },
  { id: "third", kind: "positive", text: "Added", ttlMs: 4000 },
], "enqueue should normalize and append with the default lifetime");
equal(original, [
  { id: "first", kind: "neutral", text: "Original", ttlMs: 100 },
  { id: "second", kind: "negative", text: "Keep", ttlMs: 200 },
], "enqueue must not mutate its queue");
assert(appended !== original && appended[0] !== original[0] && appended[1] !== original[1], "enqueue must copy the array and existing banners");

const replaced = enqueueBanner(original, { id: " first ", kind: "caution", text: " Changed ", ttlMs: 0 });
equal(replaced, [
  { id: "first", kind: "caution", text: "Changed", ttlMs: 0 },
  { id: "second", kind: "negative", text: "Keep", ttlMs: 200 },
], "replacement should retain its position");
assert(replaced[1] !== original[1], "replacement results must not retain unaffected banner aliases");
equal(enqueueBanner([], { id: "max", kind: "neutral", text: "Max", ttlMs: 60000 })[0].ttlMs, 60000, "60000 should be accepted");

for (const ttl of [-1, 60001, 1.5, Number.NaN, Number.POSITIVE_INFINITY]) {
  throwsType(() => enqueueBanner([], { id: "x", kind: "neutral", text: "x", ttlMs: ttl }), RangeError, "invalid lifetime should throw RangeError");
}
throwsType(() => enqueueBanner([], { id: "   ", kind: "neutral", text: "x" }), TypeError, "blank id should throw TypeError");
throwsType(() => enqueueBanner([], { id: "x", kind: "neutral", text: "\t" }), TypeError, "blank text should throw TypeError");

const duplicates: Banner[] = [
  { id: "x", kind: "neutral", text: "one", ttlMs: 1 },
  { id: "y", kind: "positive", text: "two", ttlMs: 2 },
  { id: "x", kind: "negative", text: "three", ttlMs: 3 },
];
const dismissed = dismissBanner(duplicates, "x");
equal(dismissed, [{ id: "y", kind: "positive", text: "two", ttlMs: 2 }], "dismiss should remove every exact match");
assert(dismissed !== duplicates && dismissed[0] !== duplicates[1], "dismiss should return fresh data");
const unmatched = dismissBanner(duplicates, " X ");
equal(unmatched, duplicates, "dismiss id comparison should be exact without normalization");
assert(unmatched !== duplicates && unmatched.every((banner, index) => banner !== duplicates[index]), "even unmatched dismissals must copy all data");

